package dev.mineagent.runtime.neoforge.client.webui;
import com.google.gson.*;import dev.mineagent.runtime.neoforge.client.screen.*;import dev.mineagent.runtime.neoforge.client.language.ClientLanguage;import dev.mineagent.runtime.neoforge.network.PanelSnapshotInbox;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.components.*;import java.nio.file.*;import java.util.*;
/** Actual Native/F2 language transitions; no model requests, no OS input. */
