 private static int ticks,phase,wait;private static boolean done,creating;private static JsonObject probe;private static UUID agent;private static String providerModel;
 public static boolean active(){return Boolean.getBoolean("mineagent.conversationAgentSmoke")&&System.getProperty("mineagent.conversationAgentScenario","").equals("language_ui");}
 public static void accept(JsonObject p){probe=p;}
 private static void require(boolean v,String code){if(!v)throw new IllegalStateException(code);}
